script:
// v2025.11.27.13 - 电脑端同步修复版
console.log(">>> FWB 脚本启动 v27.13");

frappe.ui.form.on("FWB Work Report", {
    // ======== 修改后的 refresh =========
    refresh(frm) {
        // [NEW v2025.12.xx] 简单判断当前是否为“手机端”
        // 这里用窗口宽度判断即可：< 992 基本就是手机 / 平板竖屏
        const is_mobile = window.innerWidth < 992;

        // ★ iOS 手机特殊处理：不要强制“纯数字键盘”，避免没有小数点 / 无法切输入法
        const is_iOS = /iP(hone|od|ad)/.test(navigator.userAgent);

        if (is_mobile && is_iOS) {
            // 这些字段常需要输入小数或切换输入法：数量、单价、时薪等
            ["qty", "custom_piece_rate", "rework_rate", "hourly_rate"].forEach(f => {
                const field = frm.fields_dict[f];
                if (field && field.$input) {
                    // 1）移除可能被框架设置的 inputmode（numeric 会害死人）
                    field.$input.removeAttr("inputmode");

                    // 2）尽量改成普通文本输入框，让系统弹出正常键盘
                    try {
                        field.$input.attr("type", "text");
                    } catch (e) {
                        // 有些浏览器不允许动态改 type，失败就算了，不影响其他逻辑
                    }
                }
            });
        }

        // [FIX] work_order 显示策略：
        // - 电脑端：强制显示（用于补录 / 修订）
        // - 手机端：不在 refresh 里改 hidden，交给 onload / 业务逻辑来控制
        if (frm.fields_dict["work_order"]) {
            if (!is_mobile) {
                // PC：永远显示
                frm.set_df_property("work_order", "hidden", 0);
            }
            // 手机端这里不做任何处理，避免覆盖 onload 里的 “没扫到工单就放出来” 逻辑
        }

        // === PC 端：确保 employee / employee_name_display 字段始终可见 ===
        if (!is_mobile) {
            ["employee", "employee_name_display"].forEach(f => {
                if (frm.fields_dict[f]) {
                    // 不隐藏
                    frm.set_df_property(f, "hidden", 0);
                    // 有些场景用的是 toggle_display，再加一层保险
                    frm.toggle_display(f, true);
                }
            });
        }


        // ======== 以下保持你原来的逻辑不变 ========

        // 2）确保这些字段在手机 / 电脑端都显示出来
        ["defect_qty", "recovered_qty", "valid_qty",
         "month_total_amount", "month_defect_rate",
         "defect_rate_panel_html"
        ].forEach(f => {
            if (frm.fields_dict[f]) {
                frm.toggle_display(f, true);
            }
        });

        // 3）样式 & 拍照按钮
        inject_css_kiosk_mode();
        setup_one_click_camera(frm);

        // [NEW] 手机端：自定义滚轮时间选择器（替代 air-datepicker 小滑块）
        if (is_mobile) {
            setup_mobile_time_picker(frm);
        }

        // 4）安全地设置 inputmode（避免桌面端只读字段没 $input 报错）
        ["start_time", "end_time", "date"].forEach(f => {
            const field = frm.fields_dict[f];
            if (field && field.$input) {
                field.$input.attr("inputmode", "none");
            }
        });

        // 5）根据计费方式 / 返工类型切换字段显示
        frm.trigger("toggle_rework_display");
        frm.trigger("wage_type");

        // 6）打开单据时，拉取该员工的当月统计（金额 + 次品率），包含旧单
        if (frm.doc.employee) {
            setTimeout(() => {
                fetch_monthly_stats(frm, frm.doc.employee);
            }, 200);
        }
    },


    // ======== 修改后的 onload =========
    onload(frm) {
        // [NEW v2025.12.xx] 同样做一个简单的“是否手机端”判断
        const is_mobile = window.innerWidth < 992;

        // 给月度历史金额一个初始值，原逻辑保留
        frm.month_history_amt = 0.0;

        // [NEW] 电脑端：一进来就让 work_order 可见
        //      手机端：默认隐藏（避免工人修改工单）
        if (frm.fields_dict["work_order"]) {
            frm.set_df_property(
                "work_order",
                "hidden",
                is_mobile ? 1 : 0
            );
        }

        // [NEW v2025.12.xx] 电脑端“历史补录”：始终展示员工相关字段，并限制候选员工
        if (!is_mobile) {
            // 1）强制显示 employee 和 employee_name_display
            ["employee", "employee_name_display"].forEach(f => {
                if (frm.fields_dict[f]) {
                    frm.toggle_display(f, true);
                }
            });

            // 2）PC 端：限制工作站下拉，不显示 打包区 / 质检区 / 发货台
            if (frm.fields_dict["workstation"] && !frm._fwb_ws_query_set) {
                frm._fwb_ws_query_set = true;

                frm.set_query("workstation", function () {
                    return {
                        filters: [
                            ["Workstation", "name", "not in", ["打包区", "质检区", "发货台"]]
                        ]
                    };
                });
            }

            // 3）只设置一次员工查询函数，避免重复绑定
            if (frm.fields_dict["employee"] && !frm._fwb_emp_query_set) {
                frm._fwb_emp_query_set = true;

                frm.set_query("employee", function () {
                    const filters = {};

                    // 如果已经选了工作站，就按当前工作站过滤员工
                    if (frm.doc.workstation) {
                        filters.workstation = frm.doc.workstation;
                    }

                    return {
                        query: "fwb_utils.fwb_manufacturing.doctype.fwb_work_report.fwb_work_report.get_production_employee_query",
                        filters: filters
                    };
                });
            }
        }

        // ===== 手机端 + 新建单据：尝试“单次”自动识别工单号 =====
        if (is_mobile && frm.is_new()) {
            const wo_scan = get_wo_param_ultimate(frm);

            if (wo_scan) {
                // URL 里带了工单号：写入字段并调用身份识别 + 路由判断
                if (!frm.doc.work_order) {
                    frm.set_value("work_order", wo_scan);
                }
                run_identity_check(frm, wo_scan);
            } else {
                // 没扫到工单号：把字段放出来，方便主管手工选
                if (frm.fields_dict["work_order"]) {
                    frm.set_df_property("work_order", "hidden", 0);
                }
                frappe.msgprint("未能从二维码中识别到工单号，请手动选择工单或联系管理员。");
            }
        }



        // 非新建单（例如手机打开历史记录），这里只做显示控制，其他逻辑保持不变
    },


    validate(frm) {
        if (!frm.doc.photo) frappe.throw("❌ 必须拍照上传！");
        calculate_total(frm);
    },

    // 字段监听
    work_order(frm) {
        if (frm.doc.work_order) frm.trigger("get_data_from_server");
        // Task 7: 计时模式下从 BOM 带入 hourly_rate
        apply_bom_hour_rate(frm);
    },

    workstation(frm) { 
        const is_mobile = window.innerWidth < 992;

        // PC 端：切换工作站时，清空原来的员工 & 姓名，避免选错站的人
        if (!is_mobile) {
            if (frm.doc.employee) {
                frm.set_value("employee", "");
            }
            if (frm.fields_dict["employee_name_display"]) {
                frm.set_value("employee_name_display", "");
            }
        }

        if(frm.doc.workstation) {
            frm.trigger("get_data_from_server"); 
            setTimeout(() => inject_css_kiosk_mode(), 500);
            // [足量提醒] 工位确定后才检测，避免抢在多工位工人选工序之前弹窗
            maybe_warn_overproduction(frm);
        }
        // Task 7: 计时模式下从 BOM 带入 hourly_rate
        apply_bom_hour_rate(frm);
    },

    // ★ 新增：当手动选择 Employee 时，同步员工姓名到 employee_name_display
    employee(frm) {
        const emp = frm.doc.employee;

        if (!emp) {
            if (frm.fields_dict["employee_name_display"]) {
                frm.set_value("employee_name_display", "");
            }
            return;
        }

        frappe.db.get_value(
            "Employee",
            emp,
            "employee_name",
            function (r) {
                if (r && r.employee_name && frm.fields_dict["employee_name_display"]) {
                    frm.set_value("employee_name_display", r.employee_name);
                }
            }
        );
    },

    get_data_from_server(frm) {
        if (!frm.doc.work_order) return;
        frappe.call({
            method: "get_piece_rate",
            args: { work_order: frm.doc.work_order, workstation: frm.doc.workstation },
            callback: function(r) {
                if (r.message) {
                    // ★ 这里新增 is_mobile 判断，避免手机端扫码时打断“任务类型选择”对话框
                    const is_mobile = window.innerWidth < 992;

                    if (!is_mobile && r.message.rate === 0 && frm.doc.workstation) {
                        frappe.msgprint({
                            title: "提示",
                            message: "未找到该工作站的计件单价",
                            indicator: "orange"
                        });
                    }
                    apply_server_data(frm, r.message);
                }
            }
        });
    },


    qty(frm) { calculate_total(frm); },
    defect_qty(frm) { calculate_total(frm); },
    recovered_qty(frm) { calculate_total(frm); },
    custom_piece_rate(frm) { calculate_total(frm); },
    rework_rate(frm) { calculate_total(frm); },
    hourly_rate(frm) { calculate_total(frm); },
    rework_type(frm) { frm.trigger("toggle_rework_display"); calculate_total(frm); },

    // ★ 修改后的：计费方式切换（计件 / 计时）
    wage_type(frm) {
        const mode = frm.doc.wage_type || "计件";

        if (mode === "计时") {
            // 计时模式：显示时薪 & 时间字段（不显示 duration 本体）
            ["hourly_rate", "start_time", "end_time", "duration_display"].forEach(f => {
                if (frm.fields_dict[f]) frm.toggle_display(f, true);
            });
            // duration 始终只作为内部计算字段，保持隐藏
            if (frm.fields_dict["duration"]) {
                frm.toggle_display("duration", false);
            }
            // 隐藏所有计件单价（无论是否返工）
            ["custom_piece_rate", "rework_rate"].forEach(f => {
                if (frm.fields_dict[f]) frm.toggle_display(f, false);
            });
        } else {
            // 计件模式：隐藏时薪 & 时间字段（包括 duration_display）
            ["hourly_rate", "start_time", "end_time", "duration_display"].forEach(f => {
                if (frm.fields_dict[f]) frm.toggle_display(f, false);
            });
            // duration 在计件模式下同样始终隐藏
            if (frm.fields_dict["duration"]) {
                frm.toggle_display("duration", false);
            }
            // 计件模式下，计件单价 / 返工单价的显示交给 toggle_rework_display 来控制
            frm.trigger("toggle_rework_display");
        }

        // 切换计费方式后，重新算金额
        calculate_total(frm);

        // 计时模式 + 已选 work_order/workstation 时, 从 BOM 自动带入 hourly_rate
        apply_bom_hour_rate(frm);
    },

    end_time(frm) { 
        if (frm.doc.end_time < frm.doc.start_time) { 
            frm.set_value('duration', 0); 
        } 
        calc_duration(frm); 
    },
    start_time(frm) { 
        calc_duration(frm); 
    },

    toggle_rework_display(frm) {
        const mode = frm.doc.wage_type || "计件";

        // 在计时模式下，不管是否返工，都隐藏所有计件相关单价
        if (mode === "计时") {
            if (frm.fields_dict["custom_piece_rate"]) {
                frm.set_df_property("custom_piece_rate", "hidden", 1);
            }
            if (frm.fields_dict["rework_rate"]) {
                frm.set_df_property("rework_rate", "hidden", 1);
            }
            return;
        }

        // 计件模式下：保持你原来的逻辑
        if (frm.doc.rework_type === "有偿返工") {
            // 显示返工单价，隐藏计件单价
            frm.set_df_property("custom_piece_rate", "hidden", 1);
            frm.set_df_property("rework_rate", "hidden", 0);
        } else {
            // 默认：显示计件单价，隐藏返工单价
            frm.set_df_property("custom_piece_rate", "hidden", 0);
            frm.set_df_property("rework_rate", "hidden", 1);
        }
    }
});

// === 辅助函数 ===


// === BOM hour_rate 自动带入并锁定 hourly_rate (Task 7) ===
function apply_bom_hour_rate(frm) {
    if (!frm || !frm.doc || !frm.fields_dict["hourly_rate"]) return;

    // 已提交单据不改字段
    if (frm.doc.docstatus === 1) return;

    // 计件模式: 解锁 hourly_rate 以恢复原状, 不带入
    if ((frm.doc.wage_type || "计件") !== "计时") {
        frm.set_df_property("hourly_rate", "read_only", 0);
        frm.set_df_property("hourly_rate", "description", "");
        frm.refresh_field("hourly_rate");
        return;
    }

    if (!frm.doc.work_order || !frm.doc.workstation) {
        // 信息不全, 保持当前可编辑状态, 用户可手填
        frm.set_df_property("hourly_rate", "read_only", 0);
        frm.set_df_property("hourly_rate", "description", "");
        frm.refresh_field("hourly_rate");
        return;
    }

    const requestKey = [
        frm.doc.work_order || "",
        frm.doc.workstation || "",
        frm.doc.wage_type || ""
    ].join("::");
    frm._bom_hour_rate_request_key = requestKey;

    frappe.call({
        method: "fwb_utils.fwb_manufacturing.doctype.fwb_work_report.fwb_work_report.get_bom_hour_rate",
        args: {
            work_order: frm.doc.work_order,
            workstation: frm.doc.workstation
        },
        callback: function (r) {
            if (frm._bom_hour_rate_request_key !== requestKey) return;

            const data = r && r.message ? r.message : {};
            const bomNo = data.bom_no || "";
            const bomHourRate = flt(data.hour_rate || 0);

            if (bomHourRate > 0) {
                // BOM 有标准时薪 -> 带入 + 锁定
                frm.set_value("hourly_rate", bomHourRate);
                frm.set_df_property("hourly_rate", "read_only", 1);
                frm.set_df_property(
                    "hourly_rate",
                    "description",
                    "已从 BOM " + bomNo + " / " + frm.doc.workstation +
                        " 标准时薪带入, 如需调整请改 BOM Operation.hour_rate"
                );
            } else {
                // BOM 没标准时薪 -> 解锁可编辑
                frm.set_df_property("hourly_rate", "read_only", 0);
                frm.set_df_property("hourly_rate", "description", "");
            }
            frm.refresh_field("hourly_rate");
            if (typeof calculate_total === "function") calculate_total(frm);
        }
    });
}


// [足量提醒 v2026.06.04] 扫码 + 工位确定后：本工序累计有效数量 >= 工单总数时弹软提醒，
// 防止工人扫错产品码把 B 产品计入 A 工单。可关闭、不阻断录入。
function maybe_warn_overproduction(frm) {
    // 仅手机扫码报工场景；电脑端主管补录/修订不提醒
    if (window.innerWidth >= 992) return;
    if (!frm || !frm.doc) return;
    if (frm.doc.docstatus === 1) return;
    if (!frm.doc.work_order || !frm.doc.workstation) return;

    // 只在 6 个生产工位触发（与服务端 PRODUCTION_WORKSTATIONS 对齐；质检/打包/发货不弹）
    var prod_stations = ["木工房", "底漆房", "面漆房", "装配区", "抛光区", "软包区"];
    if (prod_stations.indexOf(frm.doc.workstation) === -1) return;

    // 每个 工单+工位 组合只弹一次，避免重复打断
    var key = (frm.doc.work_order || "") + "|" + (frm.doc.workstation || "");
    if (frm._overprod_warned_key === key) return;

    frappe.call({
        method: "fwb_utils.fwb_manufacturing.doctype.fwb_work_report.fwb_work_report.get_production_progress",
        args: { work_order: frm.doc.work_order, workstation: frm.doc.workstation },
        callback: function (r) {
            var d = r && r.message ? r.message : null;
            if (!d || !d.exceeded) return;
            // 异步返回前工单/工位可能已被改动，二次校验
            if (frm.doc.work_order !== d.work_order || frm.doc.workstation !== d.workstation) return;

            frm._overprod_warned_key = key;

            var product = d.product_name ? ("（" + d.product_name + "）") : "";
            frappe.msgprint({
                title: "⚠️ 该产品可能已足量",
                indicator: "orange",
                message:
                    "<b>" + frm.doc.workstation + "</b> 工序" + product + "：<br>" +
                    "已报工 <b>" + flt(d.reported_qty) + "</b> / 工单总数 <b>" + flt(d.order_qty) + "</b>。<br><br>" +
                    "本工序累计已达到或超过工单数量，请确认是否<b>扫错了产品码</b>。<br>" +
                    "如确认无误，可点「我知道了」继续录入。",
                primary_action: {
                    label: "我知道了",
                    action: function () {
                        if (frappe.msg_dialog) frappe.msg_dialog.hide();
                    }
                }
            });
        }
    });
}

function calculate_total(frm) {
    // ✅ 已提交单据：完全不改任何字段，避免出现“更新”按钮
    if (frm.doc.docstatus === 1) {
        return;
    }

    const qty = flt(frm.doc.qty || 0);
    const defect = flt(frm.doc.defect_qty || 0);
    const recovered = flt(frm.doc.recovered_qty || 0);

    // 1. 本单有效数量（计件 / 计时都要算，用来分析效率）
    const valid_qty = qty - defect + recovered;
    if (frm.fields_dict['valid_qty']) {
        frm.set_value('valid_qty', valid_qty);
    }

    // 2. 本单金额
    let current_amount = 0;
    const wage_type = frm.doc.wage_type || "计件";

    if (wage_type === "计时") {
        // 计时模式：按 duration（秒）换算小时，再乘以时薪
        const dur_sec = flt(frm.doc.duration || 0);   // duration 存秒
        const hours = dur_sec / 3600.0;
        current_amount = hours * flt(frm.doc.hourly_rate || 0);
    } else {
        // 计件模式：保持你原来的逻辑
        if (frm.doc.rework_type === "有偿返工") {
            current_amount = valid_qty * flt(frm.doc.rework_rate || 0);
        } else {
            current_amount = valid_qty * flt(frm.doc.custom_piece_rate || 0);
        }
    }

    // 只对草稿 / 待提交单做金额和本月累计的实时预览
    if (frm.fields_dict["total_amount"]) {
        if (flt(frm.doc.total_amount) !== current_amount) {
            frm.set_value("total_amount", current_amount);
        }
    }

    if (frm.fields_dict['month_total_amount']) {
        let history = frm.month_history_amt || 0.0;
        let total = history + current_amount;
        // 草稿单，实时预览“提交后预计的本月累计金额”
        frm.set_value("month_total_amount", total);
    }
}

function fetch_monthly_stats(frm, employee_id) {
    if (!employee_id) return;

    frappe.call({
        method: "get_employee_stats",
        args: {
            employee: employee_id,
            // 金额用来排除当前单，次品率在服务端已经是“全月真实值”
            exclude_doc: frm.doc.name || null
        },
        callback: function (r) {
            if (!r.message) return;

            const d = r.message;

            // 1）本月历史金额（不含当前单）缓存给 calculate_total 用
            frm.month_history_amt = flt(d.history_amt || 0);

            // ✅ 不再对已提交单据用 set_value，避免出现“更新”按钮
            //    草稿单为了实时预览，仍然可以写入
            if (frm.fields_dict["month_defect_rate"] && frm.doc.docstatus === 0) {
                frm.set_value("month_defect_rate", d.cur_rate || 0);
            }
            // 提交后的单据，month_defect_rate 由服务器脚本统一维护，
            // 客户端只负责展示，不再改字段本身

            // 2）只渲染“上个月的次品率”说明（不要本月那一行）
            let html = "";
            if (d.last_month_name) {
                const last_rate = flt(d.last_rate || 0);
                const color = last_rate > 5 ? "red" : "green";
                // 例：📅 10月次品率：2.50%
                html = `
                    <div style="font-size:12px; color:#666;">
                        📅 ${d.last_month_name}次品率：
                        <b style="color:${color}">${last_rate.toFixed(2)}%</b>
                    </div>
                `;
            } else {
                html = `
                    <div style="font-size:12px; color:#999;">
                        📅 上月无数据
                    </div>
                `;
            }

            // 3）优先渲染到 HTML 面板（PC + 手机都稳定显示）
