function calc_duration(frm) {
    if (!frm.doc.start_time || !frm.doc.end_time) return;

    const diff = (new Date(frm.doc.end_time) - new Date(frm.doc.start_time)) / 1000;
    const sec = diff > 0 ? diff : 0;

    // duration 用来做计算，存“秒”
    frm.set_value("duration", sec);

    // 显示为 X小时Y分钟（如果有 duration_display 字段）
    if (frm.fields_dict["duration_display"]) {
        const hours = Math.floor(sec / 3600);
        const minutes = Math.floor((sec % 3600) / 60);
        frm.set_value("duration_display", `${hours}小时${minutes}分钟`);
    }

    // 如果是计时模式，更新时间就要重新算金额
    calculate_total(frm);
}
