        // 拦截点击 → 弹出自定义滚轮
        field.$input.on("click touchstart", function(e) {
            e.preventDefault();
            e.stopPropagation();
            e.stopImmediatePropagation();

            // 关闭 air-datepicker（如果已经弹出了的话）
            if (field.datepicker && field.datepicker.hide) {
                field.datepicker.hide();
            }
            // 有些版本的 frappe 用的是 $input.data("datepicker")
            var dp = field.$input.data("datepicker");
            if (dp && dp.hide) dp.hide();

            var title = fieldname === "start_time" ? "选择开始时间" : "选择结束时间";
            show_time_wheel_picker(frm, fieldname, title);
            return false;
        });

