function build_wheel_items(min_val, max_val, selected) {
    var html = '';
    // 上方填充，让第一个元素可以滚到中间
    html += '<div class="fwb-tp-item fwb-tp-spacer"></div>';
    html += '<div class="fwb-tp-item fwb-tp-spacer"></div>';
    for (var i = min_val; i <= max_val; i++) {
        var label = i < 10 ? "0" + i : "" + i;
        var cls = (i === selected) ? "fwb-tp-item fwb-tp-selected" : "fwb-tp-item";
        html += '<div class="' + cls + '" data-value="' + i + '">' + label + '</div>';
    }
    // 下方填充
    html += '<div class="fwb-tp-item fwb-tp-spacer"></div>';
    html += '<div class="fwb-tp-item fwb-tp-spacer"></div>';
    return html;
}

function get_selected_value($scroll) {
    var item_h = 50;
    var scroll_top = $scroll.scrollTop();
    var container_h = $scroll.height();
    var center_offset = scroll_top + container_h / 2;
    // 减去填充的 2 个 spacer
    var index = Math.round((center_offset - item_h / 2) / item_h) - 2;
    var $items = $scroll.find('.fwb-tp-item:not(.fwb-tp-spacer)');
    if (index < 0) index = 0;
    if (index >= $items.length) index = $items.length - 1;
    return parseInt($items.eq(index).data("value")) || 0;
}

