function snap_to_nearest($scroll) {
    var item_h = 50;
    var scroll_top = $scroll.scrollTop();
    var container_h = $scroll.height();
    var center_offset = scroll_top + container_h / 2;
    // 减去 2 个 spacer
    var raw_index = (center_offset / item_h) - 0.5;
    var nearest_index = Math.round(raw_index);
    var target_scroll = nearest_index * item_h - (container_h / 2) + (item_h / 2);
    $scroll.animate({ scrollTop: target_scroll }, 100, function() {
        highlight_center_item($scroll);
    });
}

function highlight_center_item($scroll) {
    var item_h = 50;
    var scroll_top = $scroll.scrollTop();
    var container_h = $scroll.height();
    var center_y = scroll_top + container_h / 2;

    $scroll.find(".fwb-tp-item").each(function(index) {
        var $item = $(this);
        var item_center = index * item_h + item_h / 2;
        var dist = Math.abs(center_y - item_center);

        if (dist < item_h * 0.6) {
            // ★ 选中项：大号加粗黑色 + 蓝色背景高亮
            $item.css({
                "color": "#000",
                "font-size": "32px",
                "font-weight": "700",
                "background": "rgba(0, 122, 255, 0.1)",
                "border-radius": "10px"
            });
        } else if (dist < item_h * 1.5) {
            // 相邻项：中等灰色
            $item.css({
                "color": "#888",
                "font-size": "22px",
                "font-weight": "400",
                "background": "transparent",
                "border-radius": "0"
            });
        } else {
            // 远处项：浅灰小字
            $item.css({
                "color": "#ccc",
                "font-size": "18px",
                "font-weight": "400",
                "background": "transparent",
                "border-radius": "0"
            });
        }
    });
}

