        });
    },

    onload(frm) {
        // 质检员：默认用当前登录用户绑定的 Employee（仅草稿单）
        if (frm.doc.docstatus === 0 && !frm.doc.inspector) {
            frappe.db.get_value("Employee", { user_id: frappe.session.user }, "name")
            .then(r => {
                if (r && r.message && r.message.name) {
                    frm.set_value("inspector", r.message.name);
