                    get_employee_details(frm, "inspector", false);
                }
            });
        }

        // 接收产品名（只在草稿 / 新建单据上自动写入）
        if (frm.doc.docstatus === 0) {
            if (frappe.route_options && frappe.route_options.product_name) {
                frm.set_value("product_name", frappe.route_options.product_name);
            } else if (frm.doc.work_order && !frm.doc.product_name) {
                frappe.call({
                    method: "frappe.client.get_value",
                    args: { 
                        doctype: "Work Order", 
                        filters: { name: frm.doc.work_order }, 
                        fieldname: ["production_item", "item_name"] 
                    },
                    callback: function(r) {
                        if (r.message) {
                            const p_name = r.message.item_name || r.message.production_item;
                            if (p_name && p_name !== r.message.production_item) {
                                frm.set_value("product_name", p_name);
                            } else {
                                frappe.db.get_value("Item", r.message.production_item, "item_name")
                                .then(res => { 
                                    if (res && res.message) {
                                        frm.set_value("product_name", res.message.item_name);
                                    }
                                });
                            }
                        }
                    }
                });
            }
        }

        // ★ 新增：从路由带入工单号（扫码场景）
        if (frappe.route_options && frappe.route_options.work_order && !frm.doc.work_order) {
            frm.set_value("work_order", frappe.route_options.work_order);
        }

        // ★ 新增：如果已经有工单号，初始化“质检用工作站列表”
        if (frm.doc.work_order) {
            init_qc_filters(frm);
        }

        // force_camera_only removed - allow gallery uploads
        init_rework_history_prompt_state(frm);
        frm.trigger("rework_action");
    },

    refresh(frm) {
        // force_camera_only removed - allow gallery uploads
        apply_specific_link_locks();

        // ★ 手机端：弱化 3 个 Link 字段的软键盘弹出，优先“点选”
        if (window.innerWidth < 992) {
            ["workstation", "employee", "from_work_report"].forEach(f => {
                const field = frm.fields_dict[f];
                if (field && field.$input) {
                    // 提示浏览器尽量不要弹软键盘
                    field.$input.attr("inputmode", "none");
                    // 关掉自动填充之类的干扰
                    field.$input.attr("autocomplete", "off");
                    field.$input.attr("autocapitalize", "off");
                    field.$input.attr("autocorrect", "off");
                }
            });
        }

        // 刷新时补一下显示信息（不改工作站）
        if (frm.doc.employee) get_employee_details(frm, "employee", false);
        if (frm.doc.inspector) get_employee_details(frm, "inspector", false);

        // 只有草稿单才在刷新时自动同步“待质检数量”和“已质检总数预览”
        if (frm.doc.docstatus === 0 && frm.doc.from_work_report) {
