        frm.trigger("toggle_penalty_display");
    },

    validate(frm) {
        // if (!frm.doc.photo) {
        //     frappe.throw("❌ 必须拍照上传！请点击“上传拍照”按钮。");
        // }
    },

    // ★ 新增：工单变更时，重置依赖字段并重新加载工作站列表
    work_order(frm) {
        frm.set_value("workstation", "");
        frm.set_value("employee", "");
        frm.set_value("from_work_report", "");
        reset_rework_history_prompt_state(frm);

        if (frm.doc.work_order) {
            init_qc_filters(frm);
        }
    },

    is_penalty(frm) {
        frm.trigger("toggle_penalty_display");
    },

    toggle_penalty_display(frm) {
        if (frm.doc.is_penalty) {
            frm.set_df_property("penalty_qty", "hidden", 0);
            frm.set_df_property("penalty_prompt", "hidden", 0);
            const prompt_html = `<div style="font-size: 13px; color: #e67e22; margin-top: 5px;">注：此数量包含在【次品数量】内。例：共有20个次品，其中10个为严重次品，此处填10</div>`;
            if (frm.fields_dict["penalty_prompt"]) {
                frm.set_df_property("penalty_prompt", "options", prompt_html);
                frm.refresh_field("penalty_prompt");
            }
        } else {
            frm.set_df_property("penalty_qty", "hidden", 1);
            frm.set_df_property("penalty_prompt", "hidden", 1);
            frm.set_value("penalty_qty", 0);
        }
    },

    rework_action(frm) {
        const action = frm.doc.rework_action;
        if (action === "次品扣除") {
            frm.toggle_display("defective_qty", true);
            frm.toggle_display("reworked_qty", false);
            frm.set_value("reworked_qty", 0);
        } 
        else if (action === "良品回补") {
            frm.toggle_display("defective_qty", false);
            frm.toggle_display("reworked_qty", true);
            frm.set_value("defective_qty", 0);
        } 
        else {
            frm.toggle_display("defective_qty", true);
            frm.toggle_display("reworked_qty", true);
        }
    },

    // ★ 修改：employee 不再清空工作站，而是“选人后自动补 from_work_report”
    employee(frm) {
        if (frm.doc.employee) {
            // 只用来显示员工姓名，不再根据员工过滤工作站
            get_employee_details(frm, "employee", false); 

            // 选完员工后，如果工单 + 工作站 都有，则尝试自动找唯一报工单
            if (frm.doc.work_order && frm.doc.workstation) {
                auto_fill_report(frm);
            }
        } else {
            // 清空描述 + 清空姓名显示字段
            frm.get_field("employee").set_description("");
            if (frm.fields_dict["employee_name_display"]) {
                frm.set_value("employee_name_display", "");
            }
        }
    },

    // ★ 修改：工作站优先于员工，从 FWB Work Report 里反查可选员工
    workstation(frm) {
        if (!frm.doc.work_order) {
            frappe.msgprint("请先选择工单号，再选择工作站。");
            frm.set_value("workstation", "");
            return;
        }

        // 每次切换工作站：清空员工 & 源报工
        frm.set_value("employee", "");
        frm.set_value("from_work_report", "");
        reset_rework_history_prompt_state(frm);

        if (!frm.doc.workstation) {
            return;
        }

        frappe.call({
            method: "get_qc_employees",
            args: {
                work_order: frm.doc.work_order,
                workstation: frm.doc.workstation
            },
            callback: function (r) {
                const data = r.message || {};
                const list = data.employees || [];

                // 设置 employee 下拉：只允许选择这些人
                if (frm.fields_dict["employee"] && list.length > 0) {
                    frm.set_query("employee", function () {
                        return {
                            filters: [
                                ["Employee", "name", "in", list.map(row => row.name)]
                            ]
                        };
                    });
                }

                // 有且仅有一人：自动填入 employee
                if (list.length === 1) {
                    frm.set_value("employee", list[0].name);
                } else if (list.length === 0) {
                    frappe.msgprint("当前工单在该工作站下还没有生产报工记录，无法质检。");
                }
            }
        });
    },

    inspector(frm) {
        if (frm.doc.inspector) {
            get_employee_details(frm, "inspector", false);
        } else {
            if (frm.fields_dict["inspector_name_display"]) {
                frm.set_value("inspector_name_display", "");
            }
            // 明确把描述清空
            frm.get_field("inspector").set_description("");
