    from_work_report(frm) {
        if (frm.doc.docstatus === 0) {
            update_qty_to_inspect(frm);
            maybe_show_rework_history_prompt(frm);
        }
    },

    // ★ 新增：当前质检数变更时，实时预览“已质检总数”
    quality_inspected(frm) {
        // 只在草稿单上做实时预览，提交后的单据不要再改动字段
        if (frm.doc.docstatus !== 0) {
            return;
        }
        const base = cint(frm._base_qc_total || 0);
        const cur = cint(frm.doc.quality_inspected || 0);
        if (frm.fields_dict["total_quality_inspected"]) {
            frm.set_value("total_quality_inspected", base + cur);
        }
    },

});

// === 一键拍照 (压缩版) ===
function setup_one_click_camera(frm) {
    const field = frm.fields_dict['photo'];
    if (!field) return;
    if (field.$wrapper.find('.custom-camera-btn').length > 0) return;
    field.$wrapper.find('.control-input').hide();

    const $btn = $(`
        <div class="custom-camera-wrapper" style="margin-top:5px;">
            <button class="btn btn-primary btn-sm custom-camera-btn" type="button" style="width: 100%; padding: 10px; font-size: 16px; border-radius: 8px;">
                📸 上传拍照
            </button>
            <div class="photo-status" style="margin-top:5px; color:green; display:none; font-weight:bold; text-align:center;">
                ✅ 已上传成功
            </div>
            <input type="file" accept="image/*" style="display:none;">
        </div>
    `);

    field.$wrapper.append($btn);
    if (frm.doc.photo) {
        $btn.find('.photo-status').show();
        $btn.find('button').text("📸 重新拍照").removeClass('btn-primary').addClass('btn-default');
    }

    $btn.find('button').on('click', function() { $btn.find('input').click(); });

    $btn.find('input').on('change', function(e) {
        const file = e.target.files[0];
        if (!file) return;

        $btn.find('button').text("🔄 压缩上传中...").prop('disabled', true);

        // 压缩逻辑
        compress_image(file, function(compressedFile) {
            let formData = new FormData();
            formData.append("file", compressedFile);
            formData.append("is_private", 1);
            formData.append("doctype", frm.doctype);
            formData.append("docname", frm.docname);
            formData.append("fieldname", "photo");

            $.ajax({
                url: "/api/method/upload_file",
                type: "POST",
                data: formData,
                processData: false,
                contentType: false,
                headers: { "X-Frappe-CSRF-Token": frappe.csrf_token },
                success: function(r) {
                    if (r.message && r.message.file_url) {
                        frm.set_value("photo", r.message.file_url);
                        $btn.find('button').text("📸 重新拍照").prop('disabled', false).removeClass('btn-primary').addClass('btn-default');
                        $btn.find('.photo-status').show();
                        frappe.show_alert({message: "照片上传成功！", indicator: "green"});
                    }
                },
                error: function() {
                    $btn.find('button').text("❌ 失败，点击重试").prop('disabled', false);
                    frappe.msgprint("照片上传失败，请检查网络。");
                }
            });
        });
    });
}

function compress_image(file, callback) {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = function(event) {
        const img = new Image();
        img.src = event.target.result;
        img.onload = function() {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;
            const MAX_WIDTH = 1280; 
            const MAX_HEIGHT = 1280;

            if (width > height) {
                if (width > MAX_WIDTH) { height *= MAX_WIDTH / width; width = MAX_WIDTH; }
            } else {
                if (height > MAX_HEIGHT) { width *= MAX_HEIGHT / height; height = MAX_HEIGHT; }
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext("2d");
            ctx.drawImage(img, 0, 0, width, height);

            canvas.toBlob(function(blob) {
                const newFile = new File([blob], file.name, { type: 'image/jpeg', lastModified: Date.now() });
                callback(newFile);
            }, 'image/jpeg', 0.6);
        }
    }
}

