// 保留原来的 get_employee_details 逻辑（只是 Rework 那边不再用 trigger_station_filter=true）
function get_employee_details(frm, field_name, trigger_station_filter) {
    const emp_id = frm.doc[field_name];
    if (!emp_id) return;

    frappe.call({
        method: "get_employee_stations",
        args: { employee: emp_id },
        callback: function(r) {
            const d = r.message;
            if (!d) return;

            const emp_name = d.employee_name || "";

            if (emp_name) {
                if (field_name === "employee") {
                    // 描述可以随便改，不会把单据标记为“已修改”
                    frm.get_field("employee").set_description(
                        `<div style="margin-top: 4px; font-size: 15px; color: #2c3e50;">
                            👤 <b>${emp_name}</b>
                        </div>`
                    );

                    // 只有草稿单才真正写入“责任人姓名”字段，避免已提交单据变脏
                    if (frm.doc.docstatus === 0 && frm.fields_dict["employee_name_display"]) {
                        frm.set_value("employee_name_display", emp_name);
                    }
                } else if (field_name === "inspector") {
                    // 质检员姓名显示字段，同样只在草稿单上写值
                    if (frm.doc.docstatus === 0 && frm.fields_dict["inspector_name_display"]) {
                        frm.set_value("inspector_name_display", emp_name);
                    }
                    frm.get_field("inspector").set_description("");
                }
            }

            // 现在 Rework Record 里已经不再用“按员工过滤工作站”了，
            // 但为了兼容其他地方，这里保留 trigger_station_filter 分支
            if (trigger_station_filter) {
                let stations = d.stations || [];
                stations = stations.filter(ws =>
                    !["质检", "QC", "Quality", "打包", "Packing"].some(k => ws.includes(k))
                );
                if (stations.length > 0) {
                    frm.set_query("workstation", function() {
                        return { filters: [["Workstation", "name", "in", stations]] };
                    });
                    if (stations.length === 1) {
                        frm.set_value("workstation", stations[0]);
                    }
                } else {
                    frappe.msgprint({
                        title: "注意",
                        message: "该员工未绑定有效的生产工作站。",
                        indicator: "orange"
                    });
                    frm.set_query("workstation", function() { return {}; });
                }
            }
        }
    });
}

