// ★ 新增：根据 from_work_report 更新“待质检数量”和“已质检总数基数”
function update_qty_to_inspect(frm) {
    if (!frm.doc.from_work_report) return;
    if (!frm.fields_dict["qty_to_inspect"]) return;

    // 1) 先同步源报工单的 qty -> 待质检数量
    frappe.db.get_value(
        "FWB Work Report",
        frm.doc.from_work_report,
        "qty",
        function (r) {
            if (r && r.qty != null) {
                frm.set_value("qty_to_inspect", r.qty);
            }
        }
    );

    // 2) 再统计同一报工号下，所有【已提交】质检单的累计质检数，作为基数
    frappe.db.get_list("Rework Record", {
        filters: {
            from_work_report: frm.doc.from_work_report,
            docstatus: 1
        },
        fields: ["quality_inspected"],
        limit: 500  // 正常情况根本用不到这么多
    }).then(records => {
        let base_total = 0;
        (records || []).forEach(row => {
            base_total += cint(row.quality_inspected || 0);
        });

        // 缓存在表单对象上，用于后续实时预览
        frm._base_qc_total = base_total;

        // 3) 计算“历史基数 + 当前这张草稿上的质检数” = 实时总和
        const cur = cint(frm.doc.quality_inspected || 0);
        if (frm.fields_dict["total_quality_inspected"]) {
            frm.set_value("total_quality_inspected", base_total + cur);
        }
    });
}

function init_rework_history_prompt_state(frm) {
    if (!frm._shown_rework_history_reports) {
        frm._shown_rework_history_reports = {};
    }
}

function reset_rework_history_prompt_state(frm) {
    init_rework_history_prompt_state(frm);
    frm._current_rework_history_report = "";
}

function maybe_show_rework_history_prompt(frm) {
    init_rework_history_prompt_state(frm);

    const reportName = frm.doc.from_work_report;
    frm._current_rework_history_report = reportName || "";

    if (!reportName || frm.doc.docstatus !== 0) {
        return;
    }

    if (frm._shown_rework_history_reports[reportName]) {
        return;
    }

    frappe.call({
        method: "fwb_utils.fwb_manufacturing.doctype.rework_record.rework_record.get_rework_history_summary",
        args: {
            from_work_report: reportName
        },
        callback: function(r) {
            if (frm.doc.from_work_report !== reportName) {
                return;
            }

            const data = r.message || {};
            if (!cint(data.history_count || 0)) {
                return;
            }

            frm._shown_rework_history_reports[reportName] = true;
            show_rework_history_dialog(reportName, data);
        }
    });
}

