// === 核心逻辑 ===

function get_packing_info_and_calculate(frm, work_order) {
    frappe.call({
        method: "get_packing_info",
        args: { work_order: work_order },
        callback: function(r) {
            if (!r.message) return;
            const d = r.message;

            // 基础信息
            if (frm.is_new()) {
                if (d.product_name && !frm.doc.product_name) frm.set_value("product_name", d.product_name);
                if (d.packer_id) frm.set_value("packinger", d.packer_id);
            }

            frm.packer_name_cache = d.packer_name;
            render_packer_name(frm);

            // 不管新建还是已有，都写入汇总数据
            frm.order_total_qty = d.order_qty || 0;          // 工单总产量
            frm.history_packed_count = d.total_packed || 0;  // 当前工单所有已提交打包记录的总箱数

            const packing_fields = ["qty_per_carton", "carton_l", "carton_w", "carton_h", "gross_weight"];

            if (frm.is_new()) {
                // 有历史箱规，则自动带入
                if (d.first_record) {
                    const rec = d.first_record;
                    Promise.all([
                        frm.set_value("carton_l", rec.carton_l),
                        frm.set_value("carton_w", rec.carton_w),
                        frm.set_value("carton_h", rec.carton_h),
                        frm.set_value("qty_per_carton", rec.qty_per_carton),
                        frm.set_value("gross_weight", rec.gross_weight)
                    ]).then(() => {
                        packing_fields.forEach(f => frm.set_df_property(f, "read_only", 1));
                        frm.refresh_fields();
                        frappe.show_alert({message: "✅ 已自动填入历史箱规", indicator: "green"});
                        calculate_metrics(frm);
                    });
                } else {
                    // 首次打包，自由输入箱规
                    packing_fields.forEach(f => frm.set_df_property(f, "read_only", 0));
                    if (!frm.has_shown_first_alert) {
                        frappe.show_alert({message: "📝 首次打包，请填写箱规。", indicator: "blue"});
                        frm.has_shown_first_alert = true;
                    }
                    calculate_metrics(frm);
                }
            } else {
                // 已有单据：只需用最新汇总重新算一遍订单总览
                calculate_metrics(frm);
            }
        }
    });
}

function render_packer_name(frm) {
    let name = frm.packer_name_cache;
    if (!name && frm.doc.packinger) {
        frappe.db.get_value("Employee", frm.doc.packinger, "employee_name").then(r => {
            if (r && r.message) {
                name = r.message.employee_name;
                draw_name();
            }
        });
    } else {
        draw_name();
    }
    function draw_name() {
        const field = frm.get_field("packinger");
        if (name && field) {
            field.set_description(`<div style="margin-top: 2px; font-size: 14px; color: #2c3e50; font-weight:bold;">👤 ${name}</div>`);
        }
    }
}

// === 关键：统一“已打包箱数 / 回滚逻辑” ===
function calculate_metrics(frm) {
    const l = flt(frm.doc.carton_l);
    const w = flt(frm.doc.carton_w);
    const h = flt(frm.doc.carton_h);
    const qty_per_box = flt(frm.doc.qty_per_carton); 
    const gw_per_box = flt(frm.doc.gross_weight);   
    const current_boxes = flt(frm.doc.carton_count);      // 本次打包箱数（当前单）
    const order_qty = frm.order_total_qty || 0;           // 工单总产量
    const history_packed = frm.history_packed_count || 0; // 当前工单所有已提交单的总箱数（API 已排除取消单）

    // 1）单箱体积提示
    let vol_per_box = 0;
    if (l && w && h) {
        vol_per_box = (l * w * h) / 1000000000;
    }
    if (frm.get_field("carton_count")) {
        if (vol_per_box > 0) {
            frm.get_field("carton_count").set_description(
                `<div style="color:#2c3e50; font-weight:bold; margin-top:5px; font-size:13px;">📦 单箱: ${vol_per_box.toFixed(4)} m³</div>`
            );
        } else {
            frm.get_field("carton_count").set_description("");
        }
    }

    // 2）统一“已打包箱数”
    let total_packed_display = 0;

    if (frm.is_new()) {
        // 新建单：预览 = 历史已打包 + 当前填写箱数
        const preview_total = history_packed + current_boxes;
        total_packed_display = preview_total;

        // 只在新建时，把预览值写到字段里，便于提交保存
        if (frm.doc.packed_total !== preview_total) {
            frm.set_value("packed_total", preview_total);
        }
    } else {
        // 已存在单据（包括已提交）：只用于显示，不改字段，避免触发“提交后不可修改”
        total_packed_display = history_packed;
        // 不再 set_value("packed_total", history_packed);
    }

    // 3）渲染订单总览
    const total_field = frm.get_field("packed_total");
    if (total_field && order_qty > 0 && qty_per_box > 0) {
        const total_boxes_theory = Math.ceil(order_qty / qty_per_box) || 0;  // 理论总箱数
        const total_vol_theory = total_boxes_theory * vol_per_box;
        const total_weight_theory = (total_boxes_theory * gw_per_box) / 1000.0;
        const remain = total_boxes_theory - total_packed_display;

        const desc = `
            <div style="background:#f8f9fa; padding:12px; border-radius:8px; margin-top:10px; border:1px solid #e2e6ea; max-width: 100%;">
                <div style="color:#333; font-weight:bold; margin-bottom:6px; border-bottom:1px solid #ddd; padding-bottom:4px;">
                    📊 订单总览 (生产总数: ${order_qty})
                </div>
                <div style="display:flex; justify-content:space-between;"><span>订单总箱数:</span> <span style="font-weight:bold; color:#2196F3;">${total_boxes_theory} 箱</span></div>
                <div style="display:flex; justify-content:space-between;"><span>已打包箱数:</span> <span style="font-weight:bold;">${total_packed_display} 箱</span></div>
                <div style="display:flex; justify-content:space-between;"><span>总体积:</span> <span style="font-weight:bold;">${(total_vol_theory || 0).toFixed(3)} m³</span></div>
                <div style="display:flex; justify-content:space-between;"><span>总重量:</span> <span style="font-weight:bold;">${(total_weight_theory || 0).toFixed(3)} 吨</span></div>
                <div style="background:#fff; padding:6px; border-radius:4px; text-align:center; margin-top:8px;">
                    🚀 剩余未打: <span style="font-size:16px; font-weight:bold; color:${remain > 0 ? '#e67e22' : 'green'};">${remain > 0 ? remain : 0}</span> 箱
                </div>
            </div>
        `;

        if (frm.fields_dict["stats_panel_html"]) {
            frm.set_df_property("stats_panel_html", "options", desc);
            frm.refresh_field("stats_panel_html");
        } else {
            total_field.set_description(desc);
        }
    }
}

