});

// FWB Work Report - 列表视图：报工日期范围过滤，只影响 List View

frappe.listview_settings["FWB Work Report"] = {
    onload(listview) {
        // 1）加两个“虚拟”日期框（只用来做 UI，不直接参与过滤）
        const start_date_field = listview.page.add_field({
            label: "开始日期",
            fieldtype: "Date",
            fieldname: "fwb_start_date_filter"
        });

        const end_date_field = listview.page.add_field({
            label: "结束日期",
            fieldtype: "Date",
            fieldname: "fwb_end_date_filter"
        });

        // ⭐ 关键：把这两个控件从「标准过滤器」里摘出去
        // 让 ListView 在收集过滤条件时永远拿不到它们的值
        start_date_field._real_get_value = start_date_field.get_value.bind(start_date_field);
        end_date_field._real_get_value   = end_date_field.get_value.bind(end_date_field);

        start_date_field.get_value = function () {
            return null;          // 列表刷新时，这个字段始终视为“没填写”
        };
        end_date_field.get_value = function () {
            return null;
        };

        // 2）实际执行过滤的函数
        const apply_date_filter = () => {
            const from = start_date_field._real_get_value();
            const to   = end_date_field._real_get_value();

            // 先把原来的 report_date 过滤清掉（保留其它过滤）
            listview.filter_area.remove("report_date");

            const filters = [];

            if (from && to) {
                filters.push(["FWB Work Report", "report_date", ">=", from]);
                filters.push(["FWB Work Report", "report_date", "<=", to]);
            } else if (from) {
                filters.push(["FWB Work Report", "report_date", ">=", from]);
            } else if (to) {
                filters.push(["FWB Work Report", "report_date", "<=", to]);
            }

            if (filters.length) {
                listview.filter_area.add(filters);
            }

            listview.refresh();
        };

        // 3）监听两个日期输入框，只要改动就重新应用过滤
        start_date_field.$input.on("change", apply_date_filter);
        end_date_field.$input.on("change", apply_date_filter);
    }
};

